quests[28866] = { id = 28866, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Into the Stonecore", description = "You say that this Millhouse Manastorm and High Priestess Azil were to meet inside the Stonecore?\n\nSounds big.  We'd best get on their trail.  We don't want the Twilight's Hammer pulling off something big right under our noses.\n\nSpeak to Earthwarden Yrsa inside the Stonecore.  She's been stationed there to make sure the Twilight's Hammer doesn't try to retake the Temple of Earth.", sourceObjective = "Speak to Earthwarden Yrsa inside the Stonecore.", completion = "It's about time they sent someone to help.\n\nMillhouse Manastorm?  It sounds like we're both after the same person.", sourceObjectiveStatus = "unverified-source-field" }
quests[28867] = { id = 28867, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nethergarde Needs You!", description = "Nethergarde needs you, {class}! I have been sent here by Quartermaster Lungertz to head off Okrilla's nefarious lackeys and to recruit able-bodied heroes of the Alliance! Help us fight off the Horde!\n\nIf you are willing, take this portal in front of me to the Blasted Lands and speak with the quartermaster.", sourceObjective = "Speak to Quartermaster Lungertz at Nethergarde Keep in Blasted Lands.", completion = "Silithus, not such a great place, eh? We get a lot of you from there...", sourceObjectiveStatus = "unverified-source-field" }
quests[28868] = { id = 28868, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The View from Down Here", description = "We need to halt the construction on this Frostmane village. If we let them get too entrenched, it will be more difficult to keep them from settling here permanently.\n\nIt's time to give those brutes a gnome's-eye view of the world! Take this gnomish viewpoint equalizer and use it on the Frostmane builders to bring them down to our level. They won't be able to lift their tools and construction will come to a standstill.", sourceObjective = "Use the Viewpoint Equalizer on 5 Frostmane Builders in Frostmane Retreat.", progress = "Did you show them what it's like to be a gnome?", completion = "Well done, {name}. That'll teach them not to mess with us in our home!", sourceObjectiveStatus = "unverified-source-field" }
quests[28869] = { id = 28869, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pebble", description = "If you hadn't noticed, there's a very small elemental that has taken a liking to you. If you stay on the ground for even a few moments, I'm sure you'll spot him.\n\nYou seem to be quite adept at making friends down here. A good talent to have.", sourceObjective = "Speak to Pebble in the Shuddering Spires. If you stay on the ground long enough, he should come out of hiding to find you.", completion = "<Pebble seems quite happy to meet you.>", sourceObjectiveStatus = "unverified-source-field" }
quests[28870] = { id = 28870, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Return to the Lost City", description = "We might've taken Neferset City, but the Neferset have a new seat of power.\n\nThanks to Siamat, the powerful djinn of the south wind, the Neferset have become considerably more dangerous.\n\nWe just learned that some of Nadun's ambushed reconnaissance party managed to secure the entrance to the Lost City.\n\nGo find Captain Hadan and get whatever information you need to bring down Siamat and the Neferset scum.", sourceObjective = "Speak to Captain Hadan inside the Lost City of the Tol'vir.", completion = "Hail, {name}.  Nadun spoke highly of you.\n\nAre you here to aid us?", sourceObjectiveStatus = "unverified-source-field" }
quests[28871] = { id = 28871, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Crushing the Wildhammer", description = "The Wildhammer grow bold with their new Alliance allies. They dare press across the river. Drive them back!\n\nSeek out and crush the Wildhammer warbrands who fight in the riverbed and within the Thundermar Ruins along the north bank. The best among them carry insignias - gather them for me to prove your allegiance to the Dragonmaw cause.", sourceObjective = "Kill Wildhammer Warbrands to collect 8 Wildhammer Insignias. Named characters within the Thundermar Ruins will also carry insignias.", progress = "Show me the insignias you've collected, {class}.", completion = "Look what we have here! A single Horde {class} can demolish the Wildhammer by the dozen. What hope do they have now?", sourceObjectiveStatus = "unverified-source-field" }
quests[28872] = { id = 28872, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Total War", description = "Some of the Wildhammer still cling to the hope of reclaiming the Thundermar Ruins to the north, across the river. Burn them out! Smash open kegs of Thundermar ale. That wicked brew is potent enough to explode when set aflame.\n\nDon't ask me why.\n\nAnd don't ask me how they drink the stuff.", sourceObjective = "Smash 10 Thundermar Ale Kegs within the Thundermar Ruins.", completion = "Yes, yes. Burn them out, as you would flush groundhogs from their holes...\n\nWell done, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[28873] = { id = 28873, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Another Maw to Feed", description = "<Griff's stomach growls.>\n\nStill hungry. It's like ... every day, I'm hungry.\n\nI hear there's more food stashed up in the Thundermar Ruins across the river to the north, where all the fighting is. Bring some to my mouth.", sourceObjective = "Gather 10 Wildhammer Food Stores from the Thundermar Ruins.", progress = "<Griff licks his lips.>", completion = "<Griff greedily snatches the heap of food, enough to feed dozens of men.>\n\nGreat! This'll tide me over for ... hours!", sourceObjectiveStatus = "unverified-source-field" }
quests[28874] = { id = 28874, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hook 'em High", description = "The Wildhammer can train war gryphons faster than we can subvert and control drakes. We can't let them continue to outnumber us!\n\nHunt gryphon riders flying over the river north of Bloodgulch. Take this hook and fling it at them as they fly by. Their momentum will hurl them from their mount, right to your feet. Kill the dismounted gryphon riders!", sourceObjective = "Use the Barbed Fleshhook to dismount and kill 4 Thundermar Gryphon Riders.", completion = "You made that look easy, {name}.\n\nGet the Wildhammer off of their mounts and they're nothing!", sourceObjectiveStatus = "unverified-source-field" }
quests[28875] = { id = 28875, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bring Down the High Shaman", description = "Our scouts in the field report that High Shaman MacKilligan has moved out of Thundermar and is fighting amidst the Thundermar Ruins northwest of here, across the river.\n\nHe's a dangerous one, {name}, responsible for the deaths of many a Dragonmaw. He WILL be destroyed, that is not the question.\n\nThe question is: will you be the one to earn the glory of the kill?", sourceObjective = "Slay High Shaman MacKilligan.", completion = "The High Shaman has been brought down! Thundermar will no doubt try to send others, but on this day, the Dragonmaw are triumphant.", sourceObjectiveStatus = "unverified-source-field" }
quests[28876] = { id = 28876, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To the Mor'shan Rampart", description = "Kadrak at the Mor'shan Rampart to the north is calling for aid.\n\nThe rampart rests on the border between the Northern Barrens and Ashenvale. It is the front line in the fight against the Alliance.\n\nWe're driving the night elves out of the forest. We'll claim its resources for the Horde!\n\nTo get there, take the Gold Road north out of the Crossroads.\n\nDestiny calls!", sourceObjective = "Report to Kadrak at the Mor'shan Rampart on the border between the Northern Barrens and Ashenvale.", sourceObjectiveStatus = "unverified-source-field" }
quests[28877] = { id = 28877, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "They Call Him Swiftdagger. He Kills Harpies.", description = "There's an orc who lives in the west. At the frayed edge of the cataclysm's swath of destruction.\n\nThey call him Swiftdagger, {name}. They call him that because ... his ... actually I think that's just his name.\n\n<Nozzlepot shrugs.>\n\nAnyway, he's a harpy-killing machine. He kills harpies. Loves it. It's a living. Go and see him! See how it's done. Live the dream. You might make a career out of it.", sourceObjective = "Locate Darsok Swiftdagger in Northern Barrens.There's an orc who lives in the west. At the frayed edge of the cataclysm's swath of destruction.\n\nThey call him Swiftdagger, {name}. They call him that because... his... actually I think that's just his name.\n\n<Nozzlepot shrugs.>\n\nAnyway, he's a harpy-killing machine. He kills harpies. Loves it. It's a living. Go and see him! See how it's done. Live the dream. You might make a career out of it.", sourceObjectiveStatus = "unverified-source-field" }
quests[28878] = { id = 28878, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Winter Veil Gift" }
quests[28879] = { id = 28879, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Back To The Orphanage", description = "We had the best time with you, {name}. We wish you could be our <daddy/mama> now, but you have to take us back to Orphan Matron Aria in Dalaran.\n\nMaybe you could come visit us again sometime? We loved meeting Winterfin hatchlings and getting to see the dragon queen. No one will believe us when we say we met a Great One!\n\nWe going to miss you, {name}. We promise to write letter sometime, oki?You will be able to choose one of these rewards:", sourceObjective = "Return your ward to the Dalaran orphanage by handing in the Oracle Orphan Whistle to Orphan Matron Aria in Dalaran.", sourceObjectiveStatus = "unverified-source-field" }
quests[28880] = { id = 28880, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Back To The Orphanage", description = "Know what? You not so bad after all, {name}. You take Kekek a lot of fun places. Kekek meet a lot of new friends and do things no other pup get to do.\n\nYou, and Hemet Nesingwary, and Snowfall Glade pups all new best friends. Maybe sometime you bring Kekek that green hills book? Kekek promise to write sometimes, too, tell you how things go. Maybe even be nice to big-tongue kids sometimes.\n\nKekek gotta go back to orphan-lady Aria now, back in purple human city.You will be able to choose one of these rewards:", sourceObjective = "Return your ward to the Dalaran orphanage by handing in the Wolvar Orphan Whistle to Orphan Matron Aria in Dalaran.", sourceObjectiveStatus = "unverified-source-field" }
quests[28881] = { id = 28881, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prospector Gunstan", description = "Say... you haven't been to Southmoon Ruins yet, have you?  Oh you simply MUST.  They have all sorts of fascinating titan artifacts.  Head west, and look for the Explorers' League tents.", sourceObjective = "Report to Prospector Gunstan at Southmoon Ruins in Tanaris.", completion = "What, you here to help?", sourceObjectiveStatus = "unverified-source-field" }
quests[28882] = { id = 28882, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Victory in Tol Barad", description = "We fought hard to get a foothold on this ugly rock and there is no way we are going to let the Horde get in the way of our plans.  Keeping control of Tol Barad is our first priority and we need your help, {name}.  Fight your way to victory in Tol Barad and return to me word of your triumph.", sourceObjective = "Win a Tol Barad battle and return to Major Marsden at Baradin Base Camp in Tol Barad Peninsula.", progress = "Were you victorious against the Horde?", completion = "What's that smell?  Ah.....Smells like victory.  Your efforts in Tol Barad are a great triumph for the entire Alliance, your contributions will not be forgotten.", sourceObjectiveStatus = "unverified-source-field" }
quests[28884] = { id = 28884, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Victory in Tol Barad", description = "Maintaining control of Tol Barad is the key to our strategic plans here in the Eastern Kingdoms, {race}.  We must do whatever it takes to keep the Alliance off this island and that means we need your help.  Fight with everything you have to win control of Tol Barad and bring me word of victory.", sourceObjective = "Win a Tol Barad battle and return to Colonel Karzag at Hellscream's Grasp in Tol Barad Peninsula.", progress = "Were you victorious against the Alliance?", completion = "You bring word of victory, just as I expected!  Any triumph in Tol Barad is in turn a triumph for the Horde.  Have no doubt, your efforts here will be rewarded.", sourceObjectiveStatus = "unverified-source-field" }
quests[28885] = { id = 28885, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mr. Goldmine's Wild Ride", description = "Okay, {name}, we need to get to the earth portal at the back of the cave.\n\nI've \"procured\" a ride for us. Why walk when we can ride in style? I hope you don't mind mine carts.\n\nLet me know when you're ready.", sourceObjective = "Ride the mine cart with Initiate Goldmine to the end of the line.", completion = "Oh no! My weapons and totems!\n\nThey're destroyed!!!", sourceObjectiveStatus = "unverified-source-field" }
quests[28905] = { id = 28905, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Daily Heroic Random (1st) (Cataclysm)" }
