quests[28907] = { id = 28907, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Daily Normal Random (1st)" }
quests[28908] = { id = 28908, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Daily Normal Random (Nth)" }
quests[28909] = { id = 28909, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sauranok Will Point the Way", description = "I see you haven't yet spoken to my advisor, Sauranok the Mystic. He has been at my side since our campaign together in Northrend.\n\nTo assault the Twilight Highlands, we're going to need a map of the shoreline. I have tasked Sauranok with digging up this information. See if he can use your assistance! He is standing right next to me.", sourceObjective = "Speak with Sauranok the Mystic at Grommash Hold in Orgrimmar.", completion = "<Sauranok nods toward you.>\n\n{class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[28910] = { id = 28910, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Desecrate this Fire!", sourceObjective = "Desecrate the Alliance's Northern Stranglethorn Vale bonfire!", sourceObjectiveStatus = "unverified-source-field" }
