quests[29014] = { id = 29014, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Candy Bucket" }
quests[29015] = { id = 29015, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Miner's Fortune", description = "Hey {race}, you interested in treasure? I knew that would get your attention.\n\nWord from the river dock here is that one of the miners in the Venture Company's Boulder Lode mine just northeast of here discovered an emerald the size of your fist.\n\nI know a few buyers who'd be interested in getting their hands on something like that, and I'd be willing to go half and half on its sale. You in?", sourceObjective = "Retrieve the Cats Eye Emerald from one of the Venture Co. Overseers or Enforcers.", progress = "If only we knew which one of the miners had found the emerald, it'd be a walk in the park...", completion = "Look at the size of that thing! We're going to be rich! Let's see, according to the rates I've seen on gems going into Undermine, I should be able to figure out your cut - fifty percent, don't worry!\n\nNow let's see... I think this should do about right. Pleasure doing business with you, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[29016] = { id = 29016, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Candy Bucket" }
quests[29017] = { id = 29017, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Candy Bucket" }
quests[29018] = { id = 29018, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Candy Bucket" }
quests[29019] = { id = 29019, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Candy Bucket" }
quests[29020] = { id = 29020, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Candy Bucket" }
quests[29021] = { id = 29021, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Samophlange", description = "The Venture Company have a small research facility west of here, just past the Sludge Fen. I don't know very much about what they're doing, but did manage to discover that they're experimenting with something called a \"samophlange\".\n\nNow what the heck is a samophlange? Well, whatever it is, I want to examine it, so I need someone to go get it.\n\nI obtained a copy of their control system operating manual, you should be able to figure out how to disengage the samophlange from it.", sourceObjective = "Access the control console at the Venture Company research site.\n\nProvided item:", completion = "A variety of buttons, levers, and blinking lights are somewhat erratically arrayed on the face of the control console. A small gauge indicates that the apparatus is currently operating within optimal levels, and indicates that control valves one through three are currently open. There is a small keyhole set into the lower right side of the control panel.", sourceObjectiveStatus = "unverified-source-field" }
quests[29022] = { id = 29022, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Samophlange", description = "The three control valves are currently opened. The various readings on the control panel lead you to presume that they must be shut off before the apparatus can be shut off.", sourceObjective = "Close off the Fuel Control Valve, the Regulator Valve and the Main Control Valve then use the control console again.", progress = "Blinking lights on the control console indicate that the main control valves have not been closed off.", completion = "The lights indicating the three control valves dim as they are shut off. Green lights slowly fade into yellow, and the switch controlling the apparatus is now moveable, with the valves closed, it can be turned off.", sourceObjectiveStatus = "unverified-source-field" }
quests[29023] = { id = 29023, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Samophlange", description = "With the apparatus deactivated, the control panel can be opened up and the samophlange removed from the console. With everything else in place, all that is left is to acquire the key to unlock the console.", sourceObjective = "Get the Console Key from Tinkerer Sniggles.", progress = "The console lights are dimmed and the gauges and dials all read at their zero positions, everything idling.", completion = "Turning the key in the lock, the control console unlocks. A red light at the top of the console turns off and all power drains from the terminal.", sourceObjectiveStatus = "unverified-source-field" }
quests[29024] = { id = 29024, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Samophlange", description = "Pulling open the face of the control console reveals a dense jumble of wires, tubing and other strange mechanical objects--most of which seem to serve no practical purpose. Pushing them aside and digging deeper into the console, you find the samophlange. A tug removes it from its housing.", sourceObjective = "Return the Samophlange to Sputtervalve at Nozzlepot's Outpost in Northern Barrens.", progress = "Oh, you're back, {name}! Do you have the samophlange?", completion = "This is... er... interesting... yes. A device this complex is best analyzed by a team of skilled engineers in a clean room, painstakingly reverse engineering each component in a controlled environment.\n\nBut who has that kind of time?\n\nLet's just fire this thing up and see what it does...", sourceObjectiveStatus = "unverified-source-field" }
quests[29026] = { id = 29026, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wenikee Boltbucket", description = "I think I really put my foot into that one - it looks like I might have knocked one of the load-bearing fluxors into the spokes of the deregulator gear. We can fix this, easy. I know an expert on triple-expansion piston drives who would love to get her hands on a samophlange. Take the broken samophlange to Wenikee Boltbucket, just south of Mor'shan Rampart, she'll patch 'er right up.\n\nHey, no need to walk - this gives me the perfect opportunity to test my personal people porter device!", sourceObjective = "Bring the Broken and Battered Samophlange to Wenikee Boltbucket. Talk to Brak to teleport directly to her.", progress = "I'm very busy with my work, {class}.  Unless you have something for me, it'd be best if you moved along...", completion = "Oh, what's this? A samophlange, you say? What's a samophlange??\n\nAh... but look at the way it moves when you handle it.  And there's the sound of intricate gears inside. Oh my! I want to fix it and see what it does, don't you??", sourceObjectiveStatus = "unverified-source-field" }
quests[29027] = { id = 29027, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nugget Slugs", description = "I want to fix this samophlange, but to do that I'm going to need some supplies. I ran out of seventeen-point-five gauge nugget slugs and I'm going to need a bunch of those for the work ahead.\n\nUnfortunately, the closest place to get them is the Burning Blade farm to the southwest. The place will be heavily guarded, so be careful, but the samophlange just might be worth the risk. Search the tool buckets, then return to me when you've gathered enough nugget slugs.", sourceObjective = "Collect 10 Nugget Slugs from buckets around the Burning Blade farm to the southwest.", progress = "Do you have the nugget slugs, {name}?  I've been eyeing this Samophlange and I can't wait to tinker with it.", completion = "Great, you got them!  Now I can get to work...", sourceObjectiveStatus = "unverified-source-field" }
quests[29028] = { id = 29028, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Into Jaedenar", description = "The Shadow Council corrupts this once beautiful forest from their stronghold, Jaedenar, in the northwest.\n\nNow, one of our own is missing. We sent a lone scout by the name of Andalar Shadevale to Jaedenar, in hopes of thinning the enemy's ranks by stealth. \n\nWe have not heard from him in days, and we fear the worst. There is a small chance he may still be alive. {name}, please go at once and find him!", sourceObjective = "Find Andalar Shadevale in Jaedenar.", sourceObjectiveStatus = "unverified-source-field" }
quests[29029] = { id = 29029, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dying Knowledge", description = "<The corrupted water bubbles and froths, as if trying to break free from itself.>\n\nTake this water to our scout in the field. He should be able to purify it for our attack on the Shadow Hold's defenses!", sourceObjective = "Take the filled canteen to Andalar Shadevale.", sourceObjectiveStatus = "unverified-source-field" }
quests[29030] = { id = 29030, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Honor the Flame", description = "The Midsummer Fire Festival is a time to honor the elements.  The element of fire stirs passion within us all.  Many times, that passion pours out into aggressive actions.  But here, in this land, we focus our passion on reverence.\n\nWe will honor the flame as tradition dictates.  Will you honor the flame with us, {name}?", sourceObjective = "Honor the Earthen Ring Bonfire in Hyjal.", completion = "Honor the Mount Hyjal flame.", sourceObjectiveStatus = "unverified-source-field" }
quests[29031] = { id = 29031, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Honor the Flame", description = "The Midsummer Fire Festival is a time to honor the elements.  The element of fire stirs passion within us all.  Many times, that passion pours out into aggressive actions.  But here, in this land, we focus our passion on reverence.\n\nWe will honor the flame as tradition dictates.  Will you honor the flame with us, {name}?", sourceObjective = "Honor the Earthen Ring Bonfire in Vashj'ir.", completion = "Honor the Vashj'ir flame.", sourceObjectiveStatus = "unverified-source-field" }
quests[29032] = { id = 29032, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Get Them While They're Young", description = "I can teach you to ride a Winterspring frostsaber, but it takes time and dedication. For this to work, both saber and rider must be highly trained and both must share a bond of deep trust.\n\nThe cubs are only receptive to this training if they're introduced to their riders at a young age. Some of the cubs in the dens surrounding Frostsaber Rock are at the proper age to begin their training. If you help me gather the most promising of those cubs, I'll allow you to begin training with your own cub.", sourceObjective = "Gather 8 Frostsaber Cubs from the dens around Frostsaber Rock.", progress = "We must get the saber cubs while they're still young enough to bond with people. If they get too old, the cats will remain feral forever.", completion = "These cubs are just the right age to begin their training. A few of them even have the proper traits to be trained as mounts. As promised, I'll select one of these cubs for you to train. This fellow here seems to have an affinity for you.\n\nI'll train the more common, docile cubs for the market in Darnassus.", sourceObjectiveStatus = "unverified-source-field" }
quests[29034] = { id = 29034, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "They Grow Up So Fast", description = "I think this little fellow will be a good match for you.\n\nThis cub is going to require a lot of attention to ensure that he grows up strong and healthy. You should check up on your cub at least once each day. Feeding and caring for your Winterspring cub is the best way to build a bond of trust with him.\n\nAs your cub grows, he will shed his old whiskers and grow new ones appropriate to his size. Once your cub has shed twenty whiskers, bring him back to me along with some materials for your saddle.", sourceObjective = "Accumulate 20 Winterspring Cub Whiskers shed by your Winterspring Cub. Bring the whiskers, 20 Runecloth, 20 Rugged Leather, and 80 gold to Rivern Frostwind.", progress = "How fares your young saber?", completion = "It looks like you've done an admirable job of raising your cub, {name}. Your saber has grown up to be strong, healthy, and loyal. Both of you are well-matched.\n\nYour Winterspring frostsaber will respond to your call anytime you wish to ride together.", sourceObjectiveStatus = "unverified-source-field" }
quests[29035] = { id = 29035, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Cub's Cravings", description = "Your Winterspring cub looks at you and licks its lips. The little cat must be hungry and it's up to you to find a suitable meal for your charge.\n\nRivern Frostwind mentioned keeping some shardtooth bear meat on hand for feeding his frostsaber cubs. Perhaps your cub would enjoy some fresh shardtooth meat of its own. Various kinds of shardtooth bears can be found all over Winterspring.", sourceObjective = "Gather 6 pieces of Shardtooth Meat from any of the Shardtooth bears in Winterspring and feed them to your Winterspring Cub.", progress = "Your wintersaber cub looks at you as if to say, \"Is that it?\"", completion = "Your Winterspring cub looks happy, satisfied, and ready to curl up for a nap.", sourceObjectiveStatus = "unverified-source-field" }
quests[29036] = { id = 29036, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Honor the Flame", description = "The Midsummer Fire Festival is a time to honor the elements.  The element of fire stirs passion within us all.  Many times, that passion pours out into aggressive actions.  But here, in this land, we focus our passion on reverence.\n\nWe will honor the flame as tradition dictates.  Will you honor the flame with us, {name}?", sourceObjective = "Honor the Earthen Ring Bonfire in Deepholm.", completion = "Honor the Deepholm flame.", sourceObjectiveStatus = "unverified-source-field" }
quests[29037] = { id = 29037, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "'Borrowing' From the Winterfall", description = "Your cub looks at you expectantly. What could it want now?\n\nThe little cat licks its lips. It must be meal time again! As the cub's surrogate <father/mother> you're responsible for providing meat until it can hunt on its own.\n\nBut what if you let someone else do the hunting? The Winterfall furbolg of Winterspring usually have a lot of smoked meat on hand in both of their camps. Surely, they wouldn't miss a few pieces and your cub would get to try something new.", sourceObjective = "Obtain 6 pieces of Smoked Meat from either Winterfall furbolg camp in Winterspring and feed them to your Winterspring Cub.", progress = "Your cub still looks hungry. What's the hold up?", completion = "Your cub looks satisfied for now.", sourceObjectiveStatus = "unverified-source-field" }
quests[29038] = { id = 29038, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hunting Practice", description = "Your Winterspring cub paws playfully at your hands. Without any playmates, the cub has few chances to practice its hunting skills.\n\nPerhaps you should take your cub hunting for the small arctic hares that burrow in the snow of northern Winterspring. Bring your cub close to the mounds of snow covering the hare burrows and wait for the cub's instincts to take over.", sourceObjective = "Bring your cub near snow-covered burrows in northern Winterspring 5 times to help it learn how to hunt arctic hares.", progress = "The cub looks at you, as if asking to continue the game.", completion = "Your Winterspring cub looks tired, content, and perhaps a bit more experienced.", sourceObjectiveStatus = "unverified-source-field" }
quests[29039] = { id = 29039, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hunting Practice", description = "Your Winterspring cub paws playfully at your hands. Without any playmates, the cub has few chances to practice its hunting skills.\n\nPerhaps you should take your cub hunting for the small arctic hares that burrow in the snow of northern Winterspring. Bring your cub close to the mounds of snow covering the hare burrows and wait for the cub's instincts to take over.", sourceObjective = "Bring your cub near snow-covered burrows in northern Winterspring 5 times to help it learn how to hunt arctic hares.", completion = "Your cub looks tired, content, and perhaps a bit more experienced.", sourceObjectiveStatus = "unverified-source-field" }
quests[29040] = { id = 29040, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cub's First Toy", description = "The winterspring cub plays with a small tuft of fur from a large animal, batting the discarded hair about. While your cub looks like it's enjoying the new game, you wonder if it might get more enjoyment from a proper cat toy.\n\nWith a little bit of leather from a yeti pelt and some feathers from crazed moonkin, you could make a respectable toy. You'll need a hide from the yeti in the Ice Thistle Hills southeast of Everlook and feathers from the moonkin at the Hidden Grove or Owl Wing Thicket.", sourceObjective = "Obtain a Tough Yeti Hide from any Ice Thistle Yeti and 5 Wildkin feathers. Combine them to make a Winterspring Cat Toy and use it to play with your Winterspring Cub.", progress = "The cub looks at you. What could you be planning?", completion = "Your Wintersrping cub seems thrilled with its new toy, but there's no telling how well it will survive the cub's enthusiasm.", sourceObjectiveStatus = "unverified-source-field" }
quests[29051] = { id = 29051, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cub's First Toy", description = "The Winterspring cub plays with a small tuft of fur from a large animal, batting the discarded hair about. While your cub looks like it's enjoying the new game, you wonder if it might get more enjoyment from a proper cat toy.\n\nWith a little bit of leather from a yeti pelt and some feathers from crazed moonkin, you could make a respectable toy. You'll need a hide from the yeti in the Ice Thistle Hills southeast of Everlook and feathers from the moonkin at the Hidden Grove or Owl Wing Thicket.", sourceObjective = "Obtain a Tough Yeti Hide from any Ice Thistle Yeti and 5 Wildkin feathers. Combine them to make a Winterspring Cat Toy and use it to play with your Winterspring Cub.", progress = "The cub looks at you. What could you be planning?", completion = "Your Winterspring cub seems thrilled with its new toy, but there's no telling how well it will survive the cub's enthusiasm.", sourceObjectiveStatus = "unverified-source-field" }
quests[29052] = { id = 29052, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Cub's Cravings", description = "Your Winterspring cub looks at you and licks its lips. The little cat must be hungry and it's up to you to find a suitable meal for your charge.\n\nRivern Frostwind mentioned keeping some shardtooth bear meat on hand for feeding his frostsaber cubs. Perhaps your cub would enjoy some fresh shardtooth meat of its own. Various kinds of shardtooth bears can be found all over Winterspring.", sourceObjective = "Gather 6 pieces of Shardtooth Meat from any of the Shardtooth bears in Winterspring and feed them to your Winterspring Cub.", progress = "Your wintersaber cub looks at you as if to say, \"Is that it?\"", completion = "Your Winterspring cub looks happy, satisfied, and ready to curl up for a nap.", sourceObjectiveStatus = "unverified-source-field" }
quests[29053] = { id = 29053, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "'Borrowing' From the Winterfall", description = "Your cub looks at you expectantly. What could it want now?\n\nThe little cat licks its lips. It must be meal time again! As the cub's surrogate <father/mother> you're responsible for providing meat until it can hunt on its own.\n\nBut what if you let someone else do the hunting? The Winterfall furbolg of Winterspring usually have a lot of smoked meat on hand in both of their camps. Surely, they wouldn't miss a few pieces and your cub would get to try something new.", sourceObjective = "Obtain 6 pieces of Smoked Meat from either Winterfall furbolg camp in Winterspring and feed them to your Winterspring Cub.", progress = "Your cub still looks hungry. What's the hold up?", completion = "Your cub looks satisfied for now.", sourceObjectiveStatus = "unverified-source-field" }
quests[29054] = { id = 29054, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stink Bombs Away!", description = "Greetings, {class}!  I hope Hallow's End is treating you well.  Bah, enough of the small talk... Let's get down to business.  Undercity.  They have employed Hags and foul magic to launch petty attacks on our town.  Some may say, ignore the childish Horde.  I say, let's show them!\n\nSpeak to my sister, Gertrude, and she will send you on your way to toss some stink bombs in Undercity.", sourceObjective = "Speak to Gertrude Fenlow to gain access to a broom, then drop stink bombs in the Undercity.", sourceObjectiveStatus = "unverified-source-field" }
quests[29066] = { id = 29066, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Good News... and Bad News", description = "<Blackhorn used the power of Thol'embaar's remains to slip his bonds. But at least the inferno seems to be subsiding.>\n\n<Matoclaw will want to know what happened here. She's waiting for you back at the Grove of Aessina.>", sourceObjective = "Talk to Matoclaw at the Grove of Aessina in Mount Hyjal.", completion = "What? Blackhorn helped you combat the inferno but escaped in the process? That crafty weasel!\n\nIt's not your fault, {name}. He'd probably been plotting this the moment he saw the flames begin creeping up the mountain. We'll have to deal with him later.", sourceObjectiveStatus = "unverified-source-field" }
quests[29067] = { id = 29067, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Potion Master", description = "Potions, potions, potions.  Can I teach you about potions!\n\nYou're going to have to bring me samples of your work, so I know you're ready.\n\nRemember {name}, you can only learn ONE specialization, so if you complete your potion training, then elixir and transmutation specialization will no longer be available.", sourceObjective = "Bring a large supply of potions to an alchemy trainer in any capital city.", progress = "Have you the potions?", completion = "Excellent!", sourceObjectiveStatus = "unverified-source-field" }
quests[29071] = { id = 29071, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Make Haste to Stormwind!", sourceObjective = "Veterans of Northrend, King Wrynn and the Alliance need your help! Stormwind and the Alliance face unprecedented threats from Deathwing and his Twilight's Hammer minions!\n\nPlease find the enclosed hearthstone and use it to transport yourself to Stormwind. The crown has arranged lodging for all returning heroes at the The Golden Keg in the Dwarven District.", sourceObjectiveStatus = "unverified-source-field" }
quests[29073] = { id = 29073, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Make Haste to Orgrimmar!", sourceObjective = "Veterans of Northrend, Warchief Garrosh commands you to return to Orgrimmar at once! You will be the blade the Horde wields against Deathwing and his Twilight's Hammer minions.\n\nUse the attached hearthstone to transport yourself to Orgrimmar. Our allies await your return, hero.", sourceObjectiveStatus = "unverified-source-field" }
quests[29074] = { id = 29074, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Season for Celebration", description = "Merry met, {class}!\n\nHallow's End is a time for celebration and reflection, though many of us have forgotten why. Indeed some aspects of the festival, like the Wickerman, have been lost to time... until now, with the return of the Gilneans to the Alliance fold.\n\nTravel outside the gates of Stormwind and speak to Celestine of the Harvest.  She can tell you more about the Wickerman ceremony.", sourceObjective = "Speak with Celestine of the Harvest just outside the gates of Stormwind.", sourceObjectiveStatus = "unverified-source-field" }
quests[29075] = { id = 29075, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Time to Gain", description = "Greetings, {class}.  The Wickerman you see before you symbolizes self.  The flames that burn it are a cleansing fire.\n\nTradition states that we take our burdens and give them to the fires.  We let go of our burdens as we approach the winter season and we gain clarity and peace.  Join us in our tradition, {class}.\n\nTake a branch from the nearby bonfire and hurl it at the Wickerman.", sourceObjective = "Use the bonfire in front of the Wickerman.", sourceObjectiveStatus = "unverified-source-field" }
quests[29078] = { id = 29078, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beating Them Back!", description = "Another Alliance recruit, eh? I'm Marshal McBride, commander of this garrison. We don't see many of your kind here, {race}, but we could sure use the help.\n\nYou've arrived just in time. The Blackrock orcs have managed to sneak into Northshire through a break in the mountain. My soldiers are doing the best that they can to push them back, but I fear they will be overwhelmed soon.\n\nHead northwest into the forest and kill the attacking Blackrock worgs! Help my soldiers!", sourceObjective = "Kill 6 Blackrock Battle Worgs.", progress = "Have you beaten back the Blackrock battle worgs?", completion = "You've bought us a little time, {name}, but we've got even bigger problems to deal with now.", sourceObjectiveStatus = "unverified-source-field" }
quests[29079] = { id = 29079, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lions for Lambs", description = "The invading orcs aren't fools. They are sizing us up, making sure that when they attack it will be to their advantage.\n\nIn the forest, to the northwest, are Blackrock spies. They peer at us through spyglasses, watching our every move - waiting. I want you take the fight to them!\n\nKill the Blackrock spies! We must show them that we know they are watching us and that we are prepared!", sourceObjective = "Kill 8 Blackrock Spies.", completion = "Excellent work, {name}. You've turned out to be quite an asset to this garrison.\n\nFeel free to speak with any of our trainers within and around the abbey if you need to sharpen any of your combat skills.\n\nWhen you're ready, I have another assignment for you...", sourceObjectiveStatus = "unverified-source-field" }
quests[29080] = { id = 29080, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Join the Battle!", description = "I have here an urgent message from Sergeant Willem. Turns out that the Blackrock orcs have hired goblin assassins. They ambushed our battalion behind the abbey. Willem has asked me to send him a hero. You have to go help them, {name}!\n\nFind Sergeant Willem north of the abbey at the command tent. Go!", sourceObjective = "Report to Sergeant Willem behind Northshire Abbey in Elwynn Forest.", completion = "It's true, we were ambushed. I don't dare send any more soldiers out there and risk losing them too. I need a volunteer. Someone willing to risk their life!", sourceObjectiveStatus = "unverified-source-field" }
quests[29081] = { id = 29081, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "They Sent Assassins", description = "Have you ever seen a goblin, {name}? They're wretched little green-skinned monsters that love only two things: gold and themselves.\n\nThe Blackrock orcs have enlisted the aid of goblin assassins to kill our soldiers. If you look to the field in the north you can barely make out their silhouettes, sneaking about in the grass.\n\nI need you to head out there and kill every goblin that you see. They need to learn that nobody messes with the Alliance!", sourceObjective = "Kill 8 Goblin Assassins.", completion = "That will teach those monsters! They'll think twice before taking another mercenary job for orcs.", sourceObjectiveStatus = "unverified-source-field" }
quests[29082] = { id = 29082, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fear No Evil", description = "Have you embraced the Holy Light yet, <brother/sister>? It is through the Holy Light that we are saved! It is through the Holy Light that I am able to heal these overly demanding soldiers! And it is through the Holy Light that you will be able to venture out into the field to the north and rescue our fallen brothers!\n\nTake this prayer book with you into the field and cast the Light's healing touch on the injured.", sourceObjective = "Revive 4 Injured Stormwind Soldiers.", progress = "Rescue our soldiers!", completion = "I think you now understand the power of the Light. The Light giveth hope, brother and the Light taketh from the darkness! BLESSED BE THE LIGHT!", sourceObjectiveStatus = "unverified-source-field" }
quests[29083] = { id = 29083, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Rear is Clear", description = "Excellent work, {name}! The rear is now officially clear. We'll take care of the stragglers. I want you to go back to Marshal McBride, standing in front of Northshire Abbey, south of here, and let him know that the goblin situation is under control.\n\nFarewell, {class}.", sourceObjective = "Report to Marshal McBride in front of Northshire Abbey in Elwynn Forest.", completion = "With your help we have managed to secure the northern and western sectors of Northshire. We still have a rather large contingency of Blackrock orcs to the east and they've begun burning down the forest!", sourceObjectiveStatus = "unverified-source-field" }
quests[29084] = { id = 29084, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Classic Random 35-39 (1st)" }
quests[29085] = { id = 29085, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Classic Random 35-39 (Nth)" }
quests[29086] = { id = 29086, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Competition Schmompetition", description = "I'm just a little guy, trying to set up my own independent business. Working hard toward the Azerothian dream, ya know?\n\nWell soon as I set up shop, the Venture Co. next door decided they wanted me out. They've been harrassing me with threatening letters, using words like 'cease' and 'desist.' \n\nWorst of all, the schematics for my newest machine are missing, and I know those corporate pilferers stole them! Go to the Sludge Fen and knock out some of their employees. I know they're hiding my blueprints!", sourceObjective = "Recover 6 of Sputtervalve's Blueprints from Venture Co. Drudgers, Mercenaries, or Peons.", progress = "I can't believe they would stoop so low! Did you get my blueprints back?", completion = "Thanks for recovering my blueprints. Now my work on the Silver Bullet X-831 can continue.", sourceObjectiveStatus = "unverified-source-field" }
quests[29087] = { id = 29087, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sludge Investigation", description = "Hey {name}, do you see this footprint? We found them all over the camp last night! Nothing's missing, but all our belongings have been...examined. The muddy trails lead back toward the Sludge Fen.\n\nSomeone's been sniffing around, and I don't like it one bit. Can you go west to the Sludge Fen and investigate? See if you can find any more tracks just like this one!", sourceObjective = "Investigate 5 Muddy Tracks at the Sludge Fen.", completion = "You look around and notice the lake is covered in slick oil. This once beautiful oasis has been ravaged. You feel a deep sense of foreboding.", sourceObjectiveStatus = "unverified-source-field" }
quests[29088] = { id = 29088, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hyena Extermination", description = "Hey {name}, we've got a real problem here. There's an overpopulation of hyenas just west of the Sludge Fen, and they're starting to become a menace.\n\nIf I have to listen to them caterwauling one more night, I just might go crazy! Vernon over there says the hyenas might even have made off with one of his stabled pigs. We can't have that happening.\n\nCan you go thin out the hyena numbers? You'll find them parading in broad daylight to the west.", sourceObjective = "Kill 6 Hecklefang Hyenas.", completion = "Good riddance! Those filthy pests are more trouble than they're worth.", sourceObjectiveStatus = "unverified-source-field" }
quests[29089] = { id = 29089, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sludge Beast!", description = "Whatever is lurking around the Sludge Fen, it doesn't appear to be human. Judging from the remains around its tracks, it's also dangerous.\n\nYou decide to follow the tracks down to the bottom of the lake and look for the creature's resting place.", sourceObjective = "Investigate the Sludge Beast's resting place and kill whatever comes out.", completion = "You saw sludge being dumped straight into the lake? I wouldn't be surprised if the Sludge Beast were a product of the Venture Co.'s carelessness.", sourceObjectiveStatus = "unverified-source-field" }
quests[29090] = { id = 29090, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Burning Threat", description = "While we cast our eyes toward the cataclysm, who watches our backs? While our leaders take up arms against Deathwing, the Burning Blade plots our downfall.\n\nEven as we speak, they are gathering recruits and supplies at the farm to the southwest. I care not to meet death at the hands of the Burning Legion. It's time we take matters into our own hands.\n\n{name}, will you help me keep the vigil? Go and slaughter their ranks before it's too late.", sourceObjective = "Kill 8 members of the Burning Blade at the farm to the southwest.", progress = "I may be old and retired, but my mind is still as sharp as my sword.", completion = "Thank you, {name}. This old orc will sleep more safely at night.", sourceObjectiveStatus = "unverified-source-field" }
quests[29091] = { id = 29091, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Freedom Movement" }
quests[29092] = { id = 29092, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Inform the Elder", description = "This information must be spread to the entirety of the Earthen Ring. I'm not certain how to proceed, but the elder who set you on this task in the first place may. Please, return to the elder and seek the next course of action - we must do something!", sourceObjective = "Travel to a capital city and speak to the Earthen Ring Elder.", completion = "This is grave news indeed. We must do everything in our power to stop this war from coming to pass.", sourceObjectiveStatus = "unverified-source-field" }
quests[29093] = { id = 29093, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cruisin' the Chasm", description = "One of my friends says that a steam tank mechanic in Westfall lets visitors use his choppers. My friend even got to ride one!\n\nI've seen people ride by the orphanage in choppers. They're real loud and just about the fastest thing I've ever seen! I want to try one out!\n\nCould we go to Sentinel Hill in Westfall and ride one of those choppers? Please? I promise to behave myself and we could see the crazy giant hole left when the world changed!", sourceObjective = "Travel to Sentinel Hill in Westfall and climb aboard a Rental Chopper to tour the Raging Chasm with your orphan.", progress = "This is going to be the best week ever!", completion = "That was the best! I want to come back and do this again next year. When I grow up, I'm going to have a chopper, except I'm gonna make it myself, and take all my friends for a ride!", sourceObjectiveStatus = "unverified-source-field" }
quests[29094] = { id = 29094, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Short Way Home", description = "Looks like your work here is done, {class}. You'd better head back to the Crossroads.\n\nLuckily for you, my Silver Bullet X-831 prototype is finished, and she's ready for a test drive. Whaddaya say you do me one last favor and take her for a little spin?\n\nOne of my assistants will accompany you. Your sweet, sweet ride is waiting on the platform behind me. Just hop on when you're ready.", sourceObjective = "Take a ride on the Silver Bullet X-831.", completion = "I thought you were a goner. Glad to see you're still in one piece.", sourceObjectiveStatus = "unverified-source-field" }
quests[29095] = { id = 29095, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Report to Thork", description = "Now that the threat here has been stilled, you should return to the Crossroads. Thork would like to speak to you.\n\nFarewell, friend.", sourceObjective = "Report to Thork at the Crossroads in the Northern Barrens.", completion = "Hello {name}. I have heard of your deeds from Darsok. You are a valuable {class} of the Horde, indeed.", sourceObjectiveStatus = "unverified-source-field" }
quests[29096] = { id = 29096, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mor'shan Caravan Pick-Up", description = "Rocco Whipshank waits for you at the road north out of the Crossroads. Let him know you are ready to accompany the caravan.", sourceObjective = "Speak to Rocco Whipshank and ride north with the Mor'shan Caravan.", sourceObjectiveStatus = "unverified-source-field" }
quests[29097] = { id = 29097, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mor'shan Caravan Rescue", description = "TBD" }
quests[29099] = { id = 29099, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mor'shan Caravan Delivery", description = "TBD" }
quests[29100] = { id = 29100, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bwemba's Spirit", description = "Dese be troublin' times for us Darkspear.  Da Zandalar be reuniting all da troll clans an' plan to take back da lands dey lost.\n\nWe tryin' to warn all dat we can.  But it might be too late.\n\nAnother Darkspear gone down to Stranglethorn to warn da people.  But it ain't safe to travel alone in Stranglethorn.\n\nHelp me find him and make sure da people in Stranglethorn are warned of da rise of da troll tribes.\n\nI gonna bind my spirit wit' ya.  When ya get to Stranglethorn, I be able to aid ya.", sourceObjective = "Warn the people of Stranglethorn and find the other Darkspear emissary.", progress = "Dis won't be no easy task, {name}.", completion = "Dere ya have it, {name}.  It look like we gonna lead an assault on da Gurubashi in Zul'Gurub.\n\nDese be dire times for us Darkspear.  But dey be even more dire for da Zandalar.  Dey goin' too far.\n\nYa been good to Bwemba, hopefully ya gonna continue to help out all of Stranglethorn.\n\nSpirits be wit' ya, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[29101] = { id = 29101, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Punting Season", description = "Baby turtles are sweet, even if they can be somewhat bitey.\n\n<Mylune holds up a bandaged finger.>\n\nBut they're so slow with their tiny little legs, they can't escape the fire creatures who are attacking Hyjal!\n\n<Mylune claps her hands together.>\n\nPLEASE save them, {name}! Pick up the wee turtles and punt them into the water of the Ashen Lake. Don't worry about the kicking, they have hard shells.\n\nThey also have hard teeth, so don't pick them up by the mouth.", sourceObjective = "Punt 5 Children of Tortolla into water.", progress = "So many tiny animals. And only so many hugs to give!", completion = "<Mylune's voice echoes in your head, along with an unwanted image of playful kittens.>\n\nYou saved the wee turtles, {name}! I hope you gently, lovingly kicked them as hard as you possibly could.", sourceObjectiveStatus = "unverified-source-field" }
quests[29102] = { id = 29102, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To Fort Livingston", description = "Da first place we check gonna be da place most likely to be attacked first.  You call it Fort Livingston.\n\nFort Livingston be surrounded by troll ruins... It make for an easy target.\n\nMaybe we find da emissary dere.  Hopefully it ain't too late.", sourceObjective = "Head to Fort Livingston in Northern Stranglethorn Vale to find the Darkspear emissary.", completion = "Another Darkspear emissary passed through some time ago telling us to be on our guard.\n\nHe mentioned some other trolls may show up, but not in spirit form, and not escorted by a {race} {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[29103] = { id = 29103, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Serpents and Poison", description = "Because of the emissary's warning we were able to gather more adventurers to help defend.  But we thought we were going to be fighting trolls.\n\nInstead we found ourselves overwhelmed by serpents!\n\nThey seem to have come from everywhere.  We are barely able to hold on, and I only suspect it's going to get worse.\n\nHelp us and eliminate the serpents and perhaps your troll friend here can use some magic to cure the poisoned.", sourceObjective = "Kill Jungle Serpents and inspect the poisoned adventurers to allow Bwemba to heal them.", progress = "It doesn't look like there is an end to these serpents.", completion = "Thanks for the help, {name}.  These serpents, there doesn't appear to be an end to them.", sourceObjectiveStatus = "unverified-source-field" }
quests[29104] = { id = 29104, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spirits Are With Us", description = "Dere was somethin' not right about dem serpents, {name}.  Dere was a trace of some bad mojo in da poison an' dat don't happen naturally.\n\nDa bonfire in da middle of da camp, we can use dat to perform a ritual.\n\nWhatever be makin' dese serpents attack, dey probably still watchin' over dem.\n\nDa only problem, {name}, is dat I only be here in spirit form.  I need you to be my hands.  I need you to go to da fire an' prepare it for me.  Den I'll handle da rest.", sourceObjective = "Prepare the bonfire in Fort Livingston for Bwemba's ritual.", progress = "Stranglethorn be in some bad shape, {name}.", completion = "Venoxis... Dis can't be good, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[29105] = { id = 29105, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nesingwary Will Know", description = "Great, just what we need, the Gurubashi on the rampage using serpents to lead the charge.  Well at least we know that much.\n\nIt's probably a safe bet that the hunters at Nesingwary's Expedition have some insight into this.  If they don't they at least know how to fight the serpents.\n\nHead there and let them know what you saw here.  Let them know that the trolls are using serpents as their weapon.", sourceObjective = "Warn the hunters at Nesingwary's Expedition in Northern Stranglethorn Vale.", completion = "We know all about the serpents, {name}.  But there is something else out there lurking...  The jungle has come to life, {class}!", sourceObjectiveStatus = "unverified-source-field" }
quests[29106] = { id = 29106, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Biggest Diamond Ever!", description = "I heard that Magni Bronzebeard, who used to be the king of Ironforge, turned into a giant diamond! Is that true? How does someone just turn into a diamond? Maybe you have to be a king and that's why no one's done it before.\n\nCan we go see him? He should be in the part of Ironforge called Old Ironforge underneath the High Seat.", sourceObjective = "Take your Human Orphan into Old Ironforge, beneath the High Seat, to visit the resting place of King Magni Bronzebeard. Make sure to call for him if he is not present when you arrive.", progress = "I've never met a king before.", completion = "So King Magni didn't wanna become a diamond? That's really sad.\n\nHey, shamans work with rocks and the earth all the time, right? Maybe one day, they'll be able to help him become a dwarf again!", sourceObjectiveStatus = "unverified-source-field" }
quests[29107] = { id = 29107, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Malfurion Has Returned!", description = "I heard that Malfurion Stormrage came back from the Emerald Dream. I don't know where that is, but it sounds like it's really far away.\n\nAnyway, he's supposed to be at the top of the Temple of the Moon in Darnassus with the High Priestess. D'you think we could go meet him? He's got to be the most powerful druid in the history of Azeroth!", sourceObjective = "Take your Human Orphan to meet Malfurion Stormrage in the Temple of the Moon in Darnassus. If your orphan is not present when you arrive, call for him.", progress = "Do you think I could be a druid one day?", completion = "That was the best! Did you see when Malfurion cast those wings on me? The other orphans are going to be sorry they missed out on this trip!", sourceObjectiveStatus = "unverified-source-field" }
quests[29109] = { id = 29109, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mor'shan Caravan Pick-Up", description = "The battle in Ashenvale rages on without relent. Our forces at the Mor'shan Ramparts are in desperate need of reinforcements and supplies.\n\nWe have a major shipment of medicines and food headed north, and I need a capable {class} like you to guard it.\n\nRocco Whipshank waits for you at the road north out of the Crossroads. Let him know you are ready to accompany the caravan.", sourceObjective = "Speak to Rocco Whipshank and ride north with the Mor'shan Caravan.", completion = "This is terrible news! {name}, at least you arrived safely.", sourceObjectiveStatus = "unverified-source-field" }
quests[29110] = { id = 29110, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mor'shan Caravan Rescue", description = "They took Balgor and the caravan supplies from our very doorstep!\n\nThose supplies are vital for our victory against the Alliance in Ashenvale, and Balgor...if anything happens to my dear little brother, I will rip every Burning Blade member to shreds myself.\n\n{name}, I need you to rescue Balgor and the captured caravan. Follow the path just north of us, up onto Dreadmist Peak. Do not let any of those Burning Blade dogs live.", sourceObjective = "Rescue Balgor Whipshank.", completion = "{name}, you came for me!", sourceObjectiveStatus = "unverified-source-field" }
quests[29111] = { id = 29111, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mor'shan Caravan Delivery", description = "You've managed to stir the Burning Blade's nest. Our scouts report that they are gathering for an attack.\n\nYou must complete the caravan's journey before they arrive. The supplies are packed, the kodos are rested, and I hope you don't mind but I made a few adjustments to your gun.\n\nIf you meet up with any resistance, shoot first and ask questions later.\n\nQuickly! They come! Speak to me when you are ready to leave.", sourceObjective = "Defend the Mor'shan Caravan.", completion = "Some days we gain quarter, other days we are beaten back behind our walls. Every day, we bury more of our brothers and sisters.\n\n<Kadrak pauses and takes a deep breath.>\n\nNot only have the supplies you brought strengthened our troops, but your heroic deeds have inspired them as well. Thank you, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[29112] = { id = 29112, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Demon Seed", description = "Listen {name}, we can't leave quite yet. I managed to overhear their plans while they were preparing for the ritual sacrifice.\n\nThey're planning to use a powerful artifact called the Demon Seed to launch a full scale attack on the Horde. They're keeping it under close guard over in that cave.\n\nIf you can get your hands on the Demon Seed, we should take it to my sister Nagala. She'll know what to do with it.", sourceObjective = "Obtain the Demon Seed.", progress = "What did you find at the top of the mountain?", completion = "{name}, you're back! Balgor made it down before you, and he's already eaten two bowls of raptor stew. Considering that his appetite hasn't suffered, I'm sure he will be fit to travel in no time.\n\nI'll make sure that this artifact is taken care of. You've done us a great service today.", sourceObjectiveStatus = "unverified-source-field" }
quests[29114] = { id = 29114, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Track the Tracker", description = "We've been fending off serpents for days now, {name}.  But the serpents are nothing compared to what else is out in that jungle.\n\nWe hunters are being hunted.\n\nA large panther named Mauti has been dragging my men off into the bush.\n\nWe sent Grent Direhammer, one of our best hunters, to track this beast down.\n\nDirehammer headed off to the east, perhaps you can find them there.", sourceObjective = "Find Grent Direhammer in Northern Stranglethorn Vale.", completion = "Shhh....", sourceObjectiveStatus = "unverified-source-field" }
quests[29115] = { id = 29115, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Hunter's Revenge", description = "The beast that's been hunting us... I've been hunting it.\n\nWe call him Mauti.  He's a clever one.  But he made a grave mistake when he killed my brother.  Now that mistake is going to cost him.  Ol' Direhammer has got his scent.\n\nI've noticed him roaming just above Kurzen's Compound.  If we act fast, we can take him down.\n\nAre you ready, {name}?", sourceObjective = "Give Grent Direhammer the closure he needs by killing Mauti.", sourceObjectiveStatus = "unverified-source-field" }
quests[29116] = { id = 29116, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Follow That Cat", description = "Well, that explains why Mauti seemed smaller...  The real Mauti has run off with Grent Direhammer, but being the wise hunter that he is, he has fired flares off so you can track him.  Find Direhammer before it's too late!", sourceObjective = "Find where Mauti has taken Grent Direhammer.", progress = "Don't be underestimating Mauti, she be a smart panther, {name}.", completion = "We be here... Da hunter, he be in da cave.  Da beast... Sometin' ain't right about her...", sourceObjectiveStatus = "unverified-source-field" }
quests[29117] = { id = 29117, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Let's Go Fly a Kite", description = "The other day, when some of us were out with the matron, I saw a gnome pushing a cart filled with toys. He had dolls, copper racers, leather balls, and some kites. I've always wanted to get a dragon kite and the matron said that if I saved all my money I could buy one, but that's going to be a long time.\n\nI think the gnome's name was Craggle Wobbletop or something like that. If we can find him, could we get some kites and fly them together? I saw him walking around the canals outside the Trade District.", sourceObjective = "Purchase a Dragon Kite Two-Pack from Craggle Wobbletop in Stormwind and then use it to fly kites with your Human Orphan. If your orphan is not present, call for him.", progress = "I thought for sure I was going to have to save all my money for like a million years to get a kite!", completion = "Thanks for the kite, {name}. Every time I fly it, I'll remember the day you gave it to me!", sourceObjectiveStatus = "unverified-source-field" }
quests[29118] = { id = 29118, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Follow That Cat", description = "The real Mauti has run off with Grent Direhammer, but being the wise hunter that he is, he has fired flares off so you can track him.  Find Direhammer before it's too late!", sourceObjective = "Find where Mauti has taken Grent Direhammer.", sourceObjectiveStatus = "unverified-source-field" }
quests[29119] = { id = 29119, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "You Scream, I Scream...", description = "There's a brand new ice cream shop in Stormwind, and it's not just any old ice cream either. This ice cream is made by mages! You don't think I'm going to be hungry fifteen minutes after eating it, do you?\n\nI bet it tastes really good. Let's go try it!\n\nI heard some of the other kids talking about it, and they were saying the store is called The Cone of Cold and it's over near the Blue Recluse in the Mage Quarter.", sourceObjective = "Purchase ice cream at The Cone of Cold and then share it with your orphan.", progress = "Ice cream is my favorite.", completion = "Do you think the apprentices mind freezing all that ice cream? I wish I got to make ice cream at school. That would make lessons a lot more fun, don't you think?", sourceObjectiveStatus = "unverified-source-field" }
quests[29120] = { id = 29120, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mauti", description = "I got da feeling dat somethin' ain't right wit' dat panther, {name}.  It ain't natural.  I gonna need to perform some rituals over da body.  Put Mauti down, an' den let's see what we can find out, {name}.", sourceObjective = "Bring Bwemba to the remains of Mauti.", progress = "Mauti, she got some powerful mojo, {name}.", completion = "High Priestess Kilnara be behind dis abomination.  Dis ain't looking good.  We should see to da dwarf and then make our way to see what other trouble be going on.", sourceObjectiveStatus = "unverified-source-field" }
quests[29121] = { id = 29121, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bury Me With Me Boots...", description = "Ah... It's you, {name}.  Mauti... He's dead?  Then my brother has been avenged.  I've only one request from ya... This scamp here, he's been pawing at me bare feet.  No dwarf should go to the earth with bare feet.\n\nPlease, bury me with me boots.", sourceObjective = "Collect Grent Direhammer's boots.", progress = "Do ya have me boots?  Grant a dwarf his last request will ya?", completion = "Th-thank ye, lad.\n\nPappy...?\n\n\nIs that...\n\n\n\nyou...\n\n\n\n\n...", sourceObjectiveStatus = "unverified-source-field" }
quests[29122] = { id = 29122, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Echoes of Nemesis", description = "<Mylune's voice sings like a melody in your head.>\n\nRemember that awful fire turtle, Nemesis, from the Firelands? He's dead now (yay!) but echoes of him keep trying to break through to Mount Hyjal.\n\nGo to the shores of the Ashen Lake and speak with my friend Tooga. Let him know you're ready to fight an echo of Nemesis, and the turtles will draw him into this world. Then you can hit him! Hard!\n\nHide inside of Tooga's shell if he starts to erupt.", sourceObjective = "Speak with Tooga to summon and kill Nemesis. Stand under Tooga's shell to protect you from Nemesis' Molten Fury.", progress = "So many animals in trouble. So few hugs to give!", completion = "Hooray! It just goes to show you, when a turtle puts his mind to something -\n\n<Mylune is distracted by a butterfly and never finishes her thought.>", sourceObjectiveStatus = "unverified-source-field" }
quests[29123] = { id = 29123, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rage Against the Flames", description = "Of all of our tasks here in Hyjal, the most pressing is simple: destroy these invaders. The very nature of fire is that it is all-consuming. Lower your defense for just a moment and it will destroy everything in sight.\n\nKill any of the fiery invaders you find. Every enemy defeated purchases more time for Hyjal.", sourceObjective = "Kill any 6 invaders from the Firelands in the Regrowth or Sethria's Roost.", completion = "Well-fought, {name}. Take a break from the flames for a while.\n\nHyjal will live to see another day, and when that day comes, I will need you alive.", sourceObjectiveStatus = "unverified-source-field" }
quests[29124] = { id = 29124, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Warn the Rebel Camp", description = "Dis death ain't be in vain, {name}.  We figure out dat Kilnara be on da prowl.  Tings don't look good.\n\nWe better check out da Rebel Camp to da north.  Maybe we find my contact dere.", sourceObjective = "Make your way to the Rebel Camp.", completion = "First we had snakes, then we had panthers, now we have trolls.\n\nIt's good that you're here, we could use all the help we can get.", sourceObjectiveStatus = "unverified-source-field" }
quests[29125] = { id = 29125, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Between the Trees", description = "Spirit fragments of Malorne - seen to us mortals as ghostly white deer - still frolic through these forests. While Malorne is no longer with us, these pieces of his spirit may be of use to us.\n\nTravel east and walk among the trees. If you are able to get close enough to one of the spirit fragments, it will bestow its power to you.\n\nOh, and take this staff. You may need it later.", sourceObjective = "Catch three Spirits of Malorne by walking close to them.", completion = "<Immediately after touching the final spirit of Malorne, you hear Matoclaw's voice.>\n\nWell done, {name}. With the horns of Malorne on our side, we stand a chance against one of the Firelands' most difficult foes: Galenges.", sourceObjectiveStatus = "unverified-source-field" }
quests[29126] = { id = 29126, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Power of Malorne", description = "<Matoclaw's voice continues.>\n\nThe portal that opened up to our east is guarded by a powerful flamewaker by the name of Galenges. We will need all of Malorne's help in defeating him.\n\nDo you remember the staff that I gave you? Place it in the pile of ash in front of the portal. Then pray that Malorne comes to your aid.", sourceObjective = "Use the Guardian's Staff to summon and defeat Galenges.", progress = "Yes?", completion = "Galenges has fallen, the unbreakable is broken... but our work is not done.", sourceObjectiveStatus = "unverified-source-field" }
quests[29127] = { id = 29127, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rage Against the Flames", description = "Of all of our tasks here in Hyjal, the most pressing is simple: destroy these invaders. The very nature of fire is that it is all-consuming. Lower your defense for just a moment and it will destroy everything in sight.\n\nKill any of the fiery invaders you find. Every enemy defeated purchases more time for Hyjal.", sourceObjective = "Kill any 8 invaders from the Firelands in the Regrowth or Sethria's Roost.", progress = "There isn't time to waste, {race}.", completion = "Well-fought, {name}. Take a break from the flames for a while.\n\nHyjal will live to see another day, and when that day comes, I will need you alive.", sourceObjectiveStatus = "unverified-source-field" }
quests[29128] = { id = 29128, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Protectors of Hyjal", description = "We need to place pressure on the assault camp at Sethria's Roost. Ragnaros' minions are using this area as a point to push their battlefront beyond the bounds of Hyjal. I'm putting you in charge of a small squad to deal with them.\n\nI have selected an elite group of fighters to assist you. Travel to Sethria's Roost. Your compatriots have been instructed to meet you once you arrive. Then put an end to the elementals' assault.", sourceObjective = "Slay 6 Fiery Behemoths or Seething Pyrelords.", progress = "I believe your assignment requires you to be in Hyjal, {race}.", completion = "A job well done, soldier. While our mission in the Firelands is critical, we must not forget about the well-being of Hyjal.\n\nSpeak with my brother again tomorrow, and he will have another squad prepared for you.", sourceObjectiveStatus = "unverified-source-field" }
quests[29129] = { id = 29129, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Legendary Engagement", description = "A pleasure, {class}.\n\n<Ziradormi smiles.>\n\nIt was kind of you to arrive so quickly.\n\nFor reasons unknown to me, my master seeks audience with you.\n\nI would counsel you not to take this invitation lightly. Anachronos seldom has cause to interact with mortals. Wisdom would dictate that you seek him out in the Caverns of Time at once.\n\nSpeak to me when you are ready and I shall personally deliver you.", sourceObjective = "Speak to Anachronos in the Caverns of Time.", completion = "It is no whimsical dalliance that brings you here, mortal.\n\nMuster every fiber of your courage for what you are about to behold.", sourceObjectiveStatus = "unverified-source-field" }
quests[29131] = { id = 29131, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Defend the Rebel Camp", description = "We are in trouble here, {name}.  Your troll friend has been through here and warned us that things were going to get serious, but I didn't think it would be this bad.\n\nWe are doing our best to hold off these trolls.  But any help you can offer would greatly help.", sourceObjective = "Help defend the Rebel Camp for three minutes.", progress = "There is no end to these trolls, {name}.", completion = "Thanks for giving us a bit of a breather, {name}.\n\nLike I said before, your troll friend was here for a small amount of time.  He warned us and then left.\n\nJames Stillair helped get him to his next destination, maybe he can help you out.\n\nGood luck out there, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[29132] = { id = 29132, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Legendary Engagement", description = "I expected that I would find you here, {class}. But then, we of the bronze flight have somewhat of an advantage when it comes to such things.\n\n<Coridormi smiles.>\n\nFor reasons unknown to me, my master seeks audience with you.\n\nI would counsel you not to take this invitation lightly, {name}. Anachronos seldom has cause to interact with mortals. Wisdom would dictate that you seek him out in the Caverns of Time at once.\n\nSpeak to me when you are ready and I shall personally deliver you.", sourceObjective = "Speak to Anachronos in the Caverns of Time.", completion = "It is no whimsical dalliance that brings you here, mortal.\n\nMuster every fiber of your courage for what you are about to behold.", sourceObjectiveStatus = "unverified-source-field" }
quests[29133] = { id = 29133, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To the Digsite", description = "The other Darkspear emissary was here briefly.  He was eager to get to the next location and warn them.   I sent him on a flight to the Explorers' League Digsite in the Cape of Stranglethorn.  I hope he wasn't too late.\n\nI will give you use of one of my gryphons, a direct flight there.\n\nTalk to me when you are ready to go, {name}.", sourceObjective = "Head to the Explorers' League Digsite in Southern Stranglethorn Vale.", progress = "We better hurry, {name}.", completion = "Dis don't look very good, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[29134] = { id = 29134, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Wrinkle in Time", description = "Listen carefully, {class}, for though we are only beginning, time already grows short and the consequences of our failure are unfathomable.\n\nAn event in the recent past has been obscured from my vision by the most powerful of magics. Its impact, however, has not.\n\nIf action is not taken to change the course of this timeline's future, the outcome is clear.\n\nBrace yourself, mortal, and behold the future of Azeroth.", sourceObjective = "Speak to Anachronos in the Caverns of Time to witness the future of Azeroth.", progress = "Witness the undoing of our world, {class}.", completion = "Now, {race}, you know the reasoning behind your summons.", sourceObjectiveStatus = "unverified-source-field" }
quests[29135] = { id = 29135, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "All-Seeing Eye", description = "I perceive the questions that burn within your mind and I must confess that I share in your uncertainty... a rare position for one such as I, and a most unsettling one.\n\nAs I scour time to find traces of this obscured event, you must aid me in the creation of an Eye, both to test your worthiness, and to provide an essential tool in the unraveling of this mystery.\n\nVenture into the Plane of Fire, {class}, and gather Eternal Embers. Bring them to me with Sands of Time and I will create the Eye.", sourceObjective = "Collect 25 Eternal Embers from The Firelands and 3 Sands of Time.", sourceObjectiveStatus = "unverified-source-field" }
quests[29137] = { id = 29137, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Breach in the Defenses", description = "Lava worms are bursting through the ground behind our lines, breaking our formations and allowing elementals to slip through. You'll find them scattered throughout our entire front to the north, and upon the Ashen Fields further out.\n\nStomp them back into their holes.", sourceObjective = "Kill 5 Lava Bursters.", completion = "We're grateful for your support. Your presence on the battlefield gives us the time we need to refortify. Your efforts make all the difference.", sourceObjectiveStatus = "unverified-source-field" }
quests[29138] = { id = 29138, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Burn Victims", description = "We have warriors out in the field who are falling wounded, and many of our druids are too busy fighting to give them proper aid. I need you to go to the north, towards the Ashen Fields, and tend their wounds at least enough that they can make it back to safety.\n\nIf you haven't any bandages or healing spells, I had Rayne put together this salve, which should prove sufficient to get them on their feet.", sourceObjective = "Heal 8 Wounded Hyjal Defenders.", progress = "To our fortune, Ragnaros' forces far more often injure our warriors than outright kill them. Their attacks naturally cauterize the wounds they inflict. It's very painful, but it's better than death.", completion = "I saw several of our warriors make it back to safety shortly after you departed. It seems your efforts were quite effective. Thank you.", sourceObjectiveStatus = "unverified-source-field" }
quests[29139] = { id = 29139, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aggressive Growth", description = "Our warriors are doing everything they can to hold back the elementals, but their numbers are endless. We need to do something to slow down the assault.\n\nFind some suitable patches of dirt or ash out on the Ashen Fields to our north and plant these seeds. They will grow deadly vines that may slow down our enemies a bit. It's not much, but every bit helps.", sourceObjective = "Plant 5 Smothervine Seeds in the Ash Piles in the Ashen Fields.", completion = "We will win this battle. Whatever it takes, we will not let these elementals back into Hyjal.", sourceObjectiveStatus = "unverified-source-field" }
quests[29140] = { id = 29140, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Under the Skylord's Gaze", description = "This is the wrong choice. Accept the quest, \"The Warden's Charge.\" Those quests are more fleshed out." }
quests[29141] = { id = 29141, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Harder They Fall", description = "Molten Behemoths have joined the elementals upon the battlefield. They are crushing our front lines. I need you to halt their momentum.\n\nYou'll find the beasts slow and clumsy. They can easily be outmaneuvered, but they will pack a devastating punch if they hit you. Be nimble, {class}.", sourceObjective = "Kill 3 Molten Behemoths.", progress = "Even with such monstrous opponents marching upon them, not a single one of my men has quit the field. Jarod is to be commended. He inspires the men like no other.", completion = "The elementals shall grow to fear you.", sourceObjectiveStatus = "unverified-source-field" }
quests[29142] = { id = 29142, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Traitors Return", description = "The Druids of the Flame assault our front line, {name}.\n\nThese vile creatures have turned their backs on Elune's teachings and worship instead the Fire Lord, Ragnaros. Twisted by his insane power, they desire nothing more than to bury us in ash.\n\nWe must counter their attack immediately!", sourceObjective = "Kill 3 Druids of the Flame.", completion = "Good. Our enemies now know that our strength is to be feared.", sourceObjectiveStatus = "unverified-source-field" }
quests[29143] = { id = 29143, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wisp Away", description = "The fire elementals are pouring out of portals on the far side of the Ashen Fields. We need someone to close them. Cut off some of their reinforcements.\n\nBanishing these kinds of elemental magics is something our wisps are perfectly suited for. One will come with you. Lead it to a portal and keep it alive until it finishes.", sourceObjective = "Lead a Hyjal Wisp to one of the fire portals in the Ashen Fields, and protect the wisp until it closes the portal. If you lose your wisp, return to Rayne Feathersong at Malfurion's Breach.", completion = "Well done, {class}. I'll have to make more use of your skills in the future.", sourceObjectiveStatus = "unverified-source-field" }
quests[29144] = { id = 29144, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Clean Up in Stormwind", description = "Greetings, {class}!  Are you enjoying Hallow's End?  It seems that in response to our stink bombing the Undercity, the Horde has decided to stink bomb our city.  The stink bombs they drop are more potent than the ones used in the past.  The power of pine won't be enough.  We will need something with a little more power.  Use this Arcane Cleanser to remove the stink bombs from the city.", sourceObjective = "Use the Arcane Cleanser to remove stink bombs around Stormwind.", sourceObjectiveStatus = "unverified-source-field" }
quests[29145] = { id = 29145, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Opening the Door", description = "You're a bit late. Hamuul, Malfurion, and some of our esteemed guests have already traveled to the invasion point, atop that cliff.\n\nOur gate to the Firelands is not yet completed, but it will be shortly. The sooner we can break through, the better.\n\nGo on! Hamuul will be expecting you.", sourceObjective = "Report to Arch Druid Hamuul Runetotem at Nordune Ridge in Mount Hyjal.", completion = "{name}. It is good to see you again. Our gate is nearly opened.", sourceObjectiveStatus = "unverified-source-field" }
quests[29146] = { id = 29146, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ridin' the Rocketway", description = "I heard that the newest members of the Horde, the goblins, built a crazy road in Azshara and it's just for rockets! Can you imagine? Ever since I heard about it, I've wanted to pay a visit. I asked Matron Battlewail about it and she said it's called the Rocketway!\n\nShe even told me they're working on a prototype rocket with two seats. D'you wanna go there and see if we can try it out? I bet the experimental rocket is near the Secret Lab at the south end of the Rocketway...", sourceObjective = "Head to the Southern Rocketway Terminus in Azshara and board the Redhound Two-Seater prototype at the top of the tower.", progress = "This is gonna be the best Children's Week ever!", completion = "That was great! I even learned how to control the rocket and everything! Did you see how I saved us? I'm gonna be a rocket pilot when I grow up!", sourceObjectiveStatus = "unverified-source-field" }
quests[29147] = { id = 29147, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Call the Flock", description = "Today, we have an opportunity to make another assault against one of Ragnaros' greater minions: Millagazor. However, we first need to get some assistance.\n\n<Matoclaw holds up a large, silky feather.>\n\nUse this artifact to invoke the power of Aviana. Once you have done so, travel northwest and gather some of her flock by calling out to them.\n\nOnce you have done so, we may proceed against Millagazor.", sourceObjective = "Use your Call the Flock ability to gather 12 Alpine Songbirds, 5 Forest Owls, and 2 Goldwing Hawks.", progress = "Yes?", completion = "<Amidst the chirps, hoots, and frenzied caws of your fellow birds, you hear the voice of Matoclaw speaking to you from afar.>\n\nWell done, {race}. Now that the flock is assembled, we strike.", sourceObjectiveStatus = "unverified-source-field" }
quests[29148] = { id = 29148, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wings Aflame", description = "<Matoclaw's voice continues to echo within your head.>\n\nMillagazor is a creature of flame, but in many ways, he is not unlike the birds of this land. As such, Aviana's artifacts may still have the power to summon him.\n\nThe fiery portal to the west is where you will find him. Use the quill near the portal's entrance, then prepare for a fierce battle.", sourceObjective = "Use the Quill of the Bird-Queen to summon and defeat Millagazor.", progress = "Earth-Mother guide your path.", completion = "Well done, champion.", sourceObjectiveStatus = "unverified-source-field" }
quests[29149] = { id = 29149, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rage Against the Flames", description = "Of all of our tasks here in Hyjal, the most pressing is simple: destroy these invaders. The very nature of fire is that it is all-consuming. Lower your defense for just a moment and it will destroy everything in sight.\n\nKill any of the fiery invaders you find. Every enemy defeated purchases more time for Hyjal.", sourceObjective = "Kill any 7 invaders from the Firelands in the Regrowth or Sethria's Roost.", completion = "Well-fought, {name}. Take a break from the flames for a while.\n\nHyjal will live to see another day, and when that day comes, I will need you alive.", sourceObjectiveStatus = "unverified-source-field" }
quests[29150] = { id = 29150, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Voodoo Zombies", description = "Da people... Dey all zombies, voodoo zombies!  Dis ain't gonna be pretty, {name}.\n\nYou gotta kill dem.\n\nBut once dey killed, dere is a moment where I can save dem.  Change dem back into da person dey were before.\n\nWe gotta act fast.  Da zombies don' rest.", sourceObjective = "Rescue 10 Digsite Survivors.", progress = "Dis be a rush job wit da voodoo.  But it still be dangerous.", completion = "We done enough, {name}.  We can't keep fighting dese zombies.  We need to figure out da source of dis voodoo.  An' I tink I know where to start...", sourceObjectiveStatus = "unverified-source-field" }
quests[29151] = { id = 29151, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bad Supplies", description = "Some of da survivors mentioned food, {name}.  We better check da food supplies.  I gotta a bad feelin' about dis.", sourceObjective = "Check out the food supplies at the Explorers' League Digsite.", completion = "Zanzil... Dis is all startin' to come together now.  If I can find my contact den we can formulate a plan of attack.  A way to end dis madness.", sourceObjectiveStatus = "unverified-source-field" }
quests[29152] = { id = 29152, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Making Contact", description = "You aren't one of the zombies...\n\nA troll?  I did see one, just before the outbreak...  He warned us, told us to be on our guard... But it was too late.\n\nYour troll friend headed to Booty Bay to warn them...", sourceObjective = "Head to Booty Bay and find Bwemba's contact.", completion = "I be tellin' Baron Revilgaz about da Zandalar threat now...", sourceObjectiveStatus = "unverified-source-field" }
quests[29153] = { id = 29153, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Booty Bay's Interests", description = "Look, {name}.  You've helped out plenty so far, but that's not going to be enough.  I need these crazy trolls stopped, or at least stopped from getting into Booty Bay.\n\nI'm going to send a man in to oversee the action, but I want you to go into Zul'Gurub and make something happen.\n\nAt the very least, I want you to find me something that will help keep these trolls out of Booty Bay.\n\nYou do that and we'll treat you right.", sourceObjective = "Recover an artifact that might keep the Zul'Gurub trolls out of Booty Bay.", progress = "Did you find something, {name}?", completion = "You killed them all?  I wish that would ease my mind, but these guys seem to have a habit of coming back from the dead.\n\nAh, but what's that you have?\n\nYou say it might keep them out of Booty Bay?\n\nNow we are talking!\n\nOh right, I said I had a reward for you?  Sure... Just give me a minute to find it.", sourceObjectiveStatus = "unverified-source-field" }
quests[29154] = { id = 29154, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Booty Bay's Interests", description = "I've been sent here by Baron Revilgaz of Booty Bay to make sure this troll menace is halted.  Or that it is at least halted at the gates of Booty Bay.\n\nI want action and I want results.\n\nI want you to get in there and kill.\n\nI want you to get in there and find me something that will help keep these trolls out of Booty Bay.\n\nYou do that and we'll make sure you get paid.", sourceObjective = "Recover an artifact that might keep the Zul'Gurub trolls out of Booty Bay.", progress = "Did you find something, {name}?", completion = "You killed them all?  I wish that would ease my mind, but these guys seem to have a habit of coming back from the dead.\n\nAh, but what's that you have?\n\nYou say it might keep them out of Booty Bay?\n\nNow we are talking!\n\nOh right, I said I had a reward for you?  Sure... Just give me a minute to find it.", sourceObjectiveStatus = "unverified-source-field" }
quests[29155] = { id = 29155, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Shiny Reward", description = "There is a stash of loot located in the statue on Janeiro's Point just northwest of Booty Bay in Stranglethorn Vale.\n\nHead to the statue and claim your prize, {class}.", sourceObjective = "Get your reward from a chest in the statue at Janeiro's Point.", completion = "Loot at last!", sourceObjectiveStatus = "unverified-source-field" }
quests[29156] = { id = 29156, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Troll Incursion", description = "A group of trolls, claiming to represent the Darkspear tribe, have arrived at Stormwind Harbor.  Our guards are keeping them at bay, for now.\n\nThe Stormwind Harbor Guards are seeking seasoned adventurers for help in removing the trolls from the harbor.  Report to Commander Sharp at Stormwind Harbor.", sourceObjective = "Speak with Commander Sharp in Stormwind Harbor.", completion = "Oh good, a {class}.  Maybe you'll have better luck in dealing with these trolls.\n\nSee what they want and then try to get rid of them.", sourceObjectiveStatus = "unverified-source-field" }
quests[29157] = { id = 29157, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Zandalari Menace", description = "The Zandalar trolls are on the move in Stranglethorn Vale!\n\nIf you wish to help the Darkspear trolls, report to Bwemba in Orgrimmar's Valley of Spirits.", sourceObjective = "Speak with Bwemba in Orgrimmar's Valley of Spirits.", completion = "Greetings, {race}.  Dese be desperate times.  Da Zandalar trolls be ready to take back dere lands.", sourceObjectiveStatus = "unverified-source-field" }
quests[29158] = { id = 29158, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Zandalar Representative", description = "{class}!  Heed my call.  Stranglethorn Vale has need of your assistance! Long ago you helped da Zandalar out before.  We not be forgetting your deeds.  It be because of your past help dat we come to you for help.  Come to me at the harbor.", sourceObjective = "Meet Bwemba at Stormwind Harbor.{class}!  Heed my call. Stranglethorn Vale has need of your assistance! Long ago you helped da Zandalar out before. We not be forgetting your deeds. It be because of your past help dat we come to you for help. Come to me at the harbor.", sourceObjectiveStatus = "unverified-source-field" }
quests[29159] = { id = 29159, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pyrorachnophobia", description = "We've fought hard to secure this area, but our foothold is tenuous.\n\nOur scouts report that the area around us is teeming with vicious fire spiders. They are the spawn of the vicious brood widow, Beth'tilac.\n\nHelp us hold our line by clearing the area of Cinderweb Spinners or Cinderweb Creepers. It will drive her mad to see her children slain.", sourceObjective = "Kill 8 Cinderweb Spinners or Cinderweb Creepers.", progress = "We cannot move the battle forward until we've cleared the area of Beth'tilac's vile spawn.", completion = "Wonderful! The more spiders we clear out, the easier it will be to push forward.", sourceObjectiveStatus = "unverified-source-field" }
quests[29160] = { id = 29160, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Egg-stinction", description = "We have a real problem on our hands. Not only are the nearby spiders vicious and predatory, their numbers appear to be endless.\n\nWe need to stop the growth of their army. Cut their heads off in the egg, not on the battlefield.\n\nThe Cinderweb Spinners' eggs are laid among the stone pillars to the north. Collect 20 eggs and bring them back to me.", sourceObjective = "Collect 20 Cinderweb Eggs from the pillars in The Widow's Clutch.", progress = "It appears the Cinderweb Spinners are the caretakers of Beth'tilac's brood.", completion = "Wonderful work, {class}. Let's hope those little spider bites aren't infectious.", sourceObjectiveStatus = "unverified-source-field" }
quests[29161] = { id = 29161, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Those Bears Up There", description = "Oh, raspberries! Just when we had saved the last bear cub from the treetops, the fires returned and scared them again!\n\nI don't know if you know this, but baby bears are precious and soft.\n\nGo to the Whistling Grove, far to the northwest. Climb the trees, grab the bear cubs, and chuck them - gently! - to the soft target in the center of the grove.\n\n<Without warning, Mylune suddenly smashes you against her bosom and begins sobbing.>\n\nLil' b-b-b-baby bears! Save them, {name}!", sourceObjective = "Climb up trees in the Whistling Grove, grab stranded Hyjal Bear Cubs, and then hurl them at the Soft Target from the top of the tree. This is perfectly safe.", progress = "<Mylune gives you the big eyes.>", completion = "<Mylune's thoughts echo in your mind, along with unwanted images of flowers and squirrels.>\n\nOh, you did it, {name}! The baby bears are so happy.\n\nI'm beginning to think they've started doing this on purpose.", sourceObjectiveStatus = "unverified-source-field" }
quests[29162] = { id = 29162, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nature's Blessing", description = "<Mylune's voice rings in your head, like the sound of birds chirping.>\n\nI love all creatures of the forest, even spiders, despite the fact that they are icky. But the spiders from the Firelands are worse than icky. They're burny, and don't belong here.\n\nFind the fire portal in the western Regrowth, and use the gem I gave you earlier to force it open. When a fire spider emerges, step on it! Unless it's big. Then, do something {class}y to it.\n\nOh, and use the gem if spider venom makes you woozy!", sourceObjective = "Use the Emerald of Aessina to summon and kill Pyrachnis.", progress = "Want to frolic a little after this?", completion = "Oh NO you're covered in SPIDER-SPORCH!\n\n<Mylune hides her eyes from the sight of you.>\n\nYou're such a brave {race}. I hope you'll go into the Firelands soon and step on ALL the spiders.", sourceObjectiveStatus = "unverified-source-field" }
quests[29163] = { id = 29163, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rage Against the Flames", description = "Of all of our tasks here in Hyjal, the most pressing is simple: destroy these invaders. The very nature of fire is that it is all-consuming. Lower your defense for just a moment and it will destroy everything in sight.\n\nKill any of the fiery invaders you find. Every enemy defeated purchases more time for Hyjal.", sourceObjective = "Kill any 9 invaders from the Firelands in the Regrowth or Sethria's Roost.", completion = "Well-fought, {name}. Take a break from the flames for a while.\n\nHyjal will live to see another day, and when that day comes, I will need you alive.", sourceObjectiveStatus = "unverified-source-field" }
quests[29164] = { id = 29164, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Perfecting Your Howl", description = "The wolf ancient, Lo'gosh - or, if you prefer, Goldrinn - has many weapons available to him, but always the most underestimated is his howl. Today, we will use this weapon to summon and defeat Lylagar, one of the lieutenants of flame that lurk within the Firelands.\n\nDefeat any of the creatures of flame within the Regrowth, and then use the Fang of the Wolf while standing atop their corpse. Soon, your howl will echo across all of Kalimdor.", sourceObjective = "Use the Fang of the Wolf atop the corpses of 10 Firelands invaders within the Regrowth.", progress = "The wolf also lives by fang, claw, and fleet of foot. It is easy to see how the howl is forgotten.", completion = "<Matoclaw's familiar voice enters your consciousness.>\n\nYes, {name}, you are ready. Now, we strike against Lylagar.", sourceObjectiveStatus = "unverified-source-field" }
quests[29165] = { id = 29165, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Call of the Pack", description = "<Matoclaw continues:>\n\nThe easternmost portal of flame is the domain of Lylagar. Stand before the portal, deliver a challenging howl, and then force the fiery beast to submit.", sourceObjective = "Use the Fang of the Wolf to summon and defeat Lylagar.", progress = "Are you beginning to see the parallels between the Firelands and our world?", completion = "I heard your triumphant cries echo across the mountain cliffs.\n\nI also heard Lylagar utter a... different type of cry.", sourceObjectiveStatus = "unverified-source-field" }
quests[29166] = { id = 29166, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Supplies for the Other Side", description = "One of the biggest dangers that our druids face when fighting within the Firelands is simple dehydration. Our proveditors spend a significant amount of time preparing canteens for the troops on the other side. We do have other methods, however.\n\nIn the greener thickets to the east, you should still find some blueroot vines which have not yet burned. These plants hold a tremendous amount of water in their roots - and also provide some energy for the weary soldier.", sourceObjective = "Obtain 7 Blueroot Vines.", progress = "Let's see... how many have you managed to gather?", completion = "I will have these packaged and shipped off right away.", sourceObjectiveStatus = "unverified-source-field" }
quests[29167] = { id = 29167, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Banshee Queen", description = "Lady Sylvanas, leader of the Forsaken, is s'posed to be one of the best warriors in the Horde, maybe even as good as the warchief himself!\n\nI've always wanted to meet her, {name}. Maybe an adventurer like you could get an audience with her! Would you take me to the Royal Quarter of the Undercity to meet Lady Sylvanas? It's a long way away and I bet the guards would never let me in by myself!", sourceObjective = "Take your orphan to meet Lady Sylvanas Windrunner in the Royal Quarter of the Undercity. Call for your orphan if he is not present when you arrive.", progress = "Children's Week is the only time I get to leave the orphanage or Orgrimmar.", completion = "She's just as fierce as I thought she'd be! But that ambassador sure got real mad when I started talking to Lady Sylvanas.", sourceObjectiveStatus = "unverified-source-field" }
quests[29169] = { id = 29169, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Beasts Within", description = "<Maywiki shuffles nervously.>\n\nAfter the fall of Hakkar, the city of the Gurubashi fell into disrepair, and the jungle claimed most of Zul'Gurub for its own.  Several powerful beasts now reside in the cracks and hollows of the ancient city.\n\nWe have seen the powers that the Gurubashi priests wield - they turn the very plantlife against us with their venomous concoctions.  Please, heroes, dispose of these beasts, before they become mindless agents of Jin'Do and his minions!", sourceObjective = "Kill the Florawing Hive Queen, Tor-Tun the Slumberer, and a Lost Offspring of Ghaz'Ranka inside of Zul'Gurub.", sourceObjectiveStatus = "unverified-source-field" }
quests[29172] = { id = 29172, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Beasts Within", description = "<Bloodslayer T'ara eyes you for a moment.>\n\nAfter de fall of Hakkar, de city of de Gurubashi fell into disrepair, and de jungle claimed most of Zul'Gurub for its own. Some powerful beasts now be livin' in da cracks an' hollows of de ancient city. \n\nWe seen de powers dem Gurubashi priests wield - dey turn de very plantlife against us wit' venomous concoctions. You tink you be strong? Dispose of dese beasts, before dey become mindless agents of Jin'do.", sourceObjective = "Kill the Florawing Hive Queen, Tor-Tun the Slumberer, and a Lost Offspring of Ghaz'Ranka inside of Zul'Gurub on Heroic difficulty.", completion = "<T'ara's tusks shift slightly.  Is she smiling?>\n\nYou done well.\n\nWe gonna rest easy tonight knowin' Jin'do an' Zanzil ain't gonna bind dem powerful beasts against us.", sourceObjectiveStatus = "unverified-source-field" }
quests[29173] = { id = 29173, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Secondary Targets", description = "Da Gurubashi trolls gathered dere most powerful allies ta rebuild Zul'Gurub an' re-take Stranglethorn Vale.\n\nChief among dem be two monstrous trolls: Kaulema da Mover an' Mor'Lek da Dismantler, an' a powerful soul-stealer called Mortaxx.\n\nDey don't be leaders of da Gurubashi, but killing dem powerful minions gonna help us prevent da rise of da Gurubashi.", sourceObjective = "Kill Kaulema the Mover, Mor'Lek the Dismantler, and Mortaxx, the Tolling Bell inside of Zul'Gurub on Heroic difficulty.", completion = "Jin'do's empire crumbles around him like da ruins of dis forsaken city.", sourceObjectiveStatus = "unverified-source-field" }
quests[29174] = { id = 29174, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Break Their Spirits", description = "A city like Zul'Gurub is similar to one of the many towering trees you see nearby.\n\nThe trunk may be thick, and the canopy vast and leafy, but without nutrients from the roots far below, the tree will wither and fall.\n\nJin'Do's army is fed largely by the actions of two minor Gurubashi trolls.  Sever these roots, and the city will fall all the easier.", sourceObjective = "Kill Gub and the Gurubashi Master Chef inside of Zul'Gurub.", sourceObjectiveStatus = "unverified-source-field" }
quests[29175] = { id = 29175, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Break Their Spirits", description = "A city like Zul'Gurub be similar ta one of de many towering trees you see nearby.\n\nDe trunk may be thick, and de canopy vast and leafy, but without nutrients from de roots far below, de tree gonna wither and fall.\n\nJin'do's army be fed largely by de actions of a couple a' minor Gurubashi trolls.  Sever dem roots, and de city gonna fall.", sourceObjective = "Kill Gub and the Gurubashi Master Chef inside of Zul'Gurub on Heroic difficulty.", progress = "You must disrupt their supply lines!", completion = "Da great Gurubashi empire begin ta wither already.\n\nIt be only a matter of time, now.", sourceObjectiveStatus = "unverified-source-field" }
quests[29176] = { id = 29176, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Fallen Chieftain", description = "Matron Battlewail says that when Cairne Bloodhoof died, the Horde lost a 'voice of wisdom'. I don't know what that means, but I always wanted to meet him. Some of the other orphans even have his hoofprint.\n\nWould you take me with you to Mulgore? Our tutor says tauren bring their dead to a place called Red Rocks to honor them. We should go there and see if we can find Cairne.", sourceObjective = "Take your orphan to Red Rocks to visit the funeral pyre of Cairne Bloodhoof. Call for your orphan if he is not present when you arrive.", progress = "I want to visit Mulgore more often.", completion = "Someday, I'm going to be a great warrior, just like Cairne or the warchief. Everyone will remember my deeds, and the ancestors will welcome my spirit too!", sourceObjectiveStatus = "unverified-source-field" }
